#!/usr/bin/env python3
"""apply_batch19_step1.py - Step 1: the timezone class of bugs.

Turns these red tests green:

  test_finished_series_is_not_read_in_the_server_timezone
  test_mongo_client_returns_timezone_aware_datetimes
  test_safe_zoneinfo_never_raises_without_the_iana_database   (new)

What it changes:

  app/db.py                 tz_aware=True on the Motor client
  app/utils/dates.py        as_utc() helper; safe_zoneinfo() can no longer raise
  app/utils/occurrences.py  THE BUG: a naive value was read in the server's zone
  app/services/*.py         four hand-rolled tzinfo patches become one as_utc()
  requirements.txt          tzdata pinned
  tests/harness.py          the fake Mongo now mirrors production
  tests/test_review_findings.py  two tests rewritten to run on Windows too

Usage:
    python apply_batch19_step1.py --check   # resolve everything, write nothing
    python apply_batch19_step1.py           # apply

Hardened after the Step 0 run on Windows:
  * every read and write is explicitly UTF-8, so a cp1252 console cannot
    truncate a file halfway through;
  * files are always written with LF, matching what git stores;
  * CRLF in your working copy no longer stops an anchor from matching;
  * content is prepared in full, then written through a temp file and an
    atomic replace, so a crash can never leave a half-written source file.
"""
from __future__ import annotations

import hashlib
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def read(path: Path) -> str:
    """UTF-8, with line endings normalised so anchors match on any platform."""
    raw = path.read_text(encoding="utf-8")
    return raw.replace("\r\n", "\n").replace("\r", "\n")


def write_atomic(path: Path, content: str) -> None:
    """Write UTF-8 + LF through a temp file, then replace in one step."""
    tmp = path.with_suffix(path.suffix + ".tmp")
    with open(tmp, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(content)
    os.replace(tmp, path)


def sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


