def main() -> int:
    check_only = "--check" in sys.argv
    planned: dict[Path, str] = {}
    notes: list[str] = []
    problems: list[str] = []

    print("apply_batch19_step1.py - the timezone class of bugs")
    print(f"repository root: {ROOT}\n")

    # ---- whole-file replacements, guarded by the expected before-hash -------
    for relative, spec in REPLACEMENTS.items():
        target = ROOT / relative
        if not target.exists():
            problems.append(f"  ! {relative} not found")
            continue
        current = read(target)
        if current == spec["content"]:
            notes.append(f"  = {relative} already at the Step 1 version")
        elif sha(current) == spec["before_sha"]:
            planned[target] = spec["content"]
            notes.append(f"  ~ {relative} replaced (was the Step 0 version)")
        else:
            problems.append(
                f"  ! {relative} is neither the Step 0 nor the Step 1 version "
                f"(sha {sha(current)}); it looks hand-edited"
            )

    # ---- surgical edits ----------------------------------------------------
    for relative, old, new, description in EDITS:
        target = ROOT / relative
        if not target.exists():
            problems.append(f"  ! {relative} not found")
            continue
        text = planned.get(target) or read(target)
        if new in text:
            notes.append(f"  = {relative}: {description} (already applied)")
            continue
        count = text.count(old)
        if count == 1:
            planned[target] = text.replace(old, new, 1)
            notes.append(f"  ~ {relative}: {description}")
        else:
            problems.append(
                f"  ! {relative}: anchor matched {count} times, expected 1 "
                f"-> {description}"
            )

    for line in notes:
        print(line)

    if problems:
        print("\nUNRESOLVED - nothing was written:")
        for line in problems:
            print(line)
        print(
            "\nThe working tree is not the one Step 1 was built against.\n"
            "Expected: branch fix/batch19-review at the Step 0 commit.\n"
            "Send me this output rather than forcing it."
        )
        return 1

    if check_only:
        print(f"\n--check: {len(planned)} file(s) would be written. Nothing changed.")
        return 0

    for target, content in planned.items():
        write_atomic(target, content)

    print(f"\nApplied. {len(planned)} file(s) written.\n")
    print(
        "Next:\n"
        "  pip install -r requirements.txt -r requirements-dev.txt\n"
        "  ruff check .\n"
        "  pytest -q\n\n"
        "Expected: 238 passed, 13 failed.\n"
        "  before Step 1: 235 passed, 15 failed\n"
        "  three tests go green, and one brand new test comes with this step.\n"
        "All 234 pre-existing tests must still pass.\n"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
